<div id="app-content"><div class="erp-page"><div class="erp-head"><div><h1>Kunden</h1><p class="erp-sub">Beim Speichern entsteht automatisch ERP/Kunden/… in deinen Nextcloud-Dateien.</p></div><a class="button primary" href="<?php p($url->linkToRoute('reinhardterp.page.customerForm')); ?>">+ Neuer Kunde</a></div><div class="erp-table"><table><thead><tr><th>Nr.</th><th>Name</th><th>Ansprechpartner</th><th>Telefon</th><th>Kundenordner</th><th></th></tr></thead><tbody><?php foreach($_['customers'] as $c): ?><tr><td><?php p($c->getCustomerNo()); ?></td><td><strong><?php p($c->getName()); ?></strong></td><td><?php p($c->getContactName()); ?></td><td><?php p($c->getPhone()); ?></td><td><code><?php p($c->getFolderPath()); ?></code></td><td class="erp-row-actions"><a class="button" href="<?php p($url->linkToRoute('reinhardterp.page.customerForm',['id'=>$c->getId()])); ?>">Bearbeiten</a><form method="post" action="<?php p($url->linkToRoute('reinhardterp.customer.archive',['id'=>$c->getId()])); ?>"><input type="hidden" name="requesttoken" value="<?php p($requestToken); ?>"><button class="button">Archivieren</button></form></td></tr><?php endforeach; ?></tbody></table><?php if(!$_['customers']): ?><p class="erp-empty">Noch keine Kunden vorhanden.</p><?php endif; ?></div></div></div>
